insert into chart_templates
  (country, code, name, name_i18n, is_default, audience, statements,
   certification_status, legal_reference, source_key)
values
  ('AD', 'default', 'Pla de comptes de referència d’Andorra', '{}'::jsonb, true, 'companies', array['AD-PGC-BAL', 'AD-PGC-PYG']::text[], null, 'Llei 30/2007 and the Pla general de comptabilitat approved by Decret 479/2025 prescribe the annual accounts (a balance sheet and an income statement, in a normal and an abridged model) and the recognition and valuation rules, but the text read prints no numbered chart of accounts: the account plan of this pack is original. Four digits, grouped like the plan the Andorran profession has long used (1 equity and long-term funds, 2 non-current assets, 3 stocks, 4 third parties and the IGI accounts, 5 financial accounts, 6 expenses, 7 income), with the names of the Pla general de comptabilitat’s headings.', 'pgc')
on conflict (country, code) do update set
  name                 = excluded.name,
  name_i18n            = excluded.name_i18n,
  is_default           = excluded.is_default,
  audience             = excluded.audience,
  statements           = excluded.statements,
  certification_status = excluded.certification_status,
  legal_reference      = excluded.legal_reference,
  source_key           = excluded.source_key;

