values
  ('AD-PGC-BAL', 'AD', 'default', 'Balanç', 'balance_sheet', 'PGC', date '2013-01-01', null, 'Llei 30/2007 (annual accounts: a balance sheet, an income statement, and in the normal model the statement of changes in equity and the cash-flow statement) and the Pla general de comptabilitat, Decret 479/2025, which sets the classification of assets and liabilities as current or non-current and the headings of equity. The printed models of the balance sheet are images in the text read, so the lines here follow the headings of the plan’s recognition rules (intangible assets, tangible assets, investment property, financial assets, stocks, cash, prepayments, equity, provisions, financial liabilities, tax) and are the pack’s own abridged layout.', 'pgc', 'combined', 'Resultat de l’exercici en curs', '{}'::jsonb),
  ('AD-PGC-PYG', 'AD', 'default', 'Compte de pèrdues i guanys', 'income_statement', 'PGC', date '2013-01-01', null, 'Pla general de comptabilitat, Decret 479/2025, section 4 (Compte de pèrdues i guanys): operating income (net turnover, change in stocks, other income), operating expenses (consumption, staff, other operating expenses, depreciation, impairment), financial result, other non-recurrent income and expenses, and the corporate income tax. The printed model is an image in the text read: the lines here are the pack’s own abridged layout over the plan’s headings.', 'pgc', null, null, '{}'::jsonb)
